USING (VALUES (1, 27.00), (7, 15.00)) AS o (Id, Precio)
    ON d.Id = o.Id
WHEN MATCHED THEN
    UPDATE SET Precio = o.Precio
WHEN NOT MATCHED THEN
    INSERT (Id, Nombre, Precio) VALUES (o.Id, N'Producto nuevo', o.Precio)
